// Synthetic Word documents for the browser tests, generated by code on every
// run. Nothing binary is checked in and no real document is ever used.
import { deflateSync } from 'node:zlib';
import { p, r, tbl, tc, tr } from '../../test/doc-layout-fixtures';
import { buildDocx, type DocxSpec } from '../../test/docx-fixtures';

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32(bytes: Uint8Array): number {
  let c = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) c = CRC_TABLE[(c ^ bytes[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Uint8Array): Uint8Array {
  const out = new Uint8Array(12 + data.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, data.length);
  for (let i = 0; i < 4; i++) out[4 + i] = type.charCodeAt(i);
  out.set(data, 8);
  view.setUint32(8 + data.length, crc32(out.subarray(4, 8 + data.length)));
  return out;
}

/** A PNG of one colour, or of two halves (left and right) when `right` is given. */
export function png(width: number, height: number, left: [number, number, number], right?: [number, number, number]): Uint8Array {
  const header = new Uint8Array(13);
  const view = new DataView(header.buffer);
  view.setUint32(0, width);
  view.setUint32(4, height);
  header[8] = 8; // bit depth
  header[9] = 2; // RGB
  const stride = 1 + width * 3;
  const raw = new Uint8Array(height * stride);
  for (let x = 0; x < width; x++) {
    const colour = right && x >= width / 2 ? right : left;
    raw.set(colour, 1 + x * 3);
  }
  // Every row is the same: the first one is copied down, which keeps a picture of many megapixels quick to make.
  for (let y = 1; y < height; y++) raw.copyWithin(y * stride, 0, stride);
  const parts = [Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', header), chunk('IDAT', deflateSync(raw)), chunk('IEND', new Uint8Array(0))];
  const out = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0));
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

const PX = 9525;

/** Arial 12 pt; no widow control, so that page breaks fall where the line count says. */
export const DOC_STYLES =
  '<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:eastAsia="Arial" w:cs="Arial"/><w:sz w:val="24"/></w:rPr></w:rPrDefault>' +
  '<w:pPrDefault><w:pPr><w:widowControl w:val="0"/></w:pPr></w:pPrDefault></w:docDefaults>';

/** A page of 600 x 400 px with margins of 40 px; header and footer 10 px from the edge. */
export const docSection = (inner = '') =>
  `<w:sectPr>${inner}<w:pgSz w:w="9000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600" w:header="150" w:footer="150" w:gutter="0"/></w:sectPr>`;

export const field = (code: string, result: string) =>
  '<w:r><w:fldChar w:fldCharType="begin"/></w:r>' +
  `<w:r><w:instrText xml:space="preserve">${code}</w:instrText></w:r>` +
  '<w:r><w:fldChar w:fldCharType="separate"/></w:r>' +
  r(result) +
  '<w:r><w:fldChar w:fldCharType="end"/></w:r>';

/** An inline picture of the given size in px, showing the part related as `rel`. */
export const picture = (width: number, height: number, rel = 'rIdImg', extra = '') =>
  `<w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${width * PX}" cy="${height * PX}"/>` +
  '<wp:docPr id="1" name="Picture 1" descr="A red and blue picture"/>' +
  '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="0" name="x"/><pic:cNvPicPr/></pic:nvPicPr>' +
  `<pic:blipFill><a:blip r:embed="${rel}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>` +
  `<pic:spPr><a:xfrm${extra}><a:off x="0" y="0"/><a:ext cx="${width * PX}" cy="${height * PX}"/></a:xfrm></pic:spPr></pic:pic></a:graphicData></a:graphic>` +
  '</wp:inline></w:drawing></w:r>';

export const link = (id: string, text: string) => `<w:hyperlink r:id="${id}">${r(text, '<w:color w:val="0000FF"/><w:u w:val="single"/>')}</w:hyperlink>`;

const BORDERS =
  '<w:tblBorders>' +
  ['top', 'left', 'bottom', 'right', 'insideH', 'insideV'].map((side) => `<w:${side} w:val="single" w:sz="16" w:space="0" w:color="00AA00"/>`).join('') +
  '</w:tblBorders>';

export const RED: [number, number, number] = [220, 0, 0];
export const BLUE: [number, number, number] = [0, 0, 220];

/**
 * A document of several pages with everything the view shows: text, a table
 * with green borders, a picture (left half red, right half blue), two
 * hyperlinks (one of them not safe), a header and a footer with the page number.
 */
export function sampleDocx(): Promise<Uint8Array> {
  let body = p(r('Document title', '<w:b/><w:sz w:val="36"/>'));
  body += p(r('See ') + link('rIdLink', 'the example site') + r(' or ') + link('rIdBad', 'do not open') + r('.'));
  body += tbl(tr(tc('Cell A') + tc('Cell B')) + tr(tc('Cell C') + tc('Cell D')), [3000, 3000], BORDERS);
  body += p(picture(120, 60));
  for (let i = 1; i <= 40; i++) body += p(`Paragraph ${i} of the sample document.`);
  body += docSection('<w:headerReference w:type="default" r:id="h1"/><w:footerReference w:type="default" r:id="f1"/>');
  return buildDocx({
    styles: DOC_STYLES,
    body,
    headers: { h1: p('Sample header') },
    footers: { f1: p(r('Page ') + field(' PAGE ', '1') + r(' of ') + field(' NUMPAGES ', '1'), '<w:jc w:val="center"/>') },
    rels: [
      ['rIdImg', 'image', 'media/image1.png'],
      ['rIdLink', 'hyperlink', 'https://example.com/docs?a=1', true],
      ['rIdBad', 'hyperlink', 'javascript:window.__hacked=1', true],
    ],
    parts: [['word/media/image1.png', png(40, 20, RED, BLUE)]],
  });
}

/** `pages` pages with one short paragraph each ("Page 1" ...), separated by page breaks. */
export function manyPagesDocx(pages: number): Promise<Uint8Array> {
  let body = '';
  for (let i = 1; i <= pages; i++) body += p(`Page ${i}`, i > 1 ? '<w:pageBreakBefore/>' : '');
  return buildDocx({ styles: DOC_STYLES, body: body + docSection() });
}

/** `count` paragraphs of a few lines each. */
export function longDocx(count: number): Promise<Uint8Array> {
  const sentence = 'The quick brown fox jumps over the lazy dog and keeps running along the river bank. ';
  let body = '';
  for (let i = 1; i <= count; i++) body += p(`${i}. ${sentence}${sentence}`);
  return buildDocx({ styles: DOC_STYLES, body: body + docSection() });
}

/** Builds a document from a body and optional extras, with the styles and the section of the samples. */
export function docx(body: string, extra: Partial<DocxSpec> = {}): Promise<Uint8Array> {
  return buildDocx({ styles: DOC_STYLES, body: body + docSection(), ...extra });
}

/** Document defaults with another font: `size` in half points. */
export const fontStyles = (family: string, size: number) =>
  `<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="${family}" w:hAnsi="${family}" w:eastAsia="${family}" w:cs="${family}"/><w:sz w:val="${size}"/></w:rPr></w:rPrDefault>` +
  '<w:pPrDefault><w:pPr><w:widowControl w:val="0"/></w:pPr></w:pPrDefault></w:docDefaults>';

/**
 * One word of `length` letters, in Arial 11 pt. The letters follow no
 * pattern, so that no cache of a browser's text measuring finds a piece of
 * the word it has measured before.
 */
export function longWordDocx(length: number): Promise<Uint8Array> {
  const letters = new Array<string>(length);
  let seed = 12345;
  for (let i = 0; i < length; i++) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    letters[i] = String.fromCharCode(97 + ((seed >>> 8) % 26));
  }
  return buildDocx({ styles: fontStyles('Arial', 22), body: p(letters.join('')) + docSection() });
}

/** `count` paragraphs of one short line each ("Line 1" ...) in the given font. */
export function linesDocx(family: string, size: number, count: number): Promise<Uint8Array> {
  let body = '';
  for (let i = 1; i <= count; i++) body += p(`Line ${i}`);
  return buildDocx({ styles: fontStyles(family, size), body: body + docSection() });
}

let hugePicture: Uint8Array | undefined;

/**
 * `count` pages, each with one picture shown at 400 x 300 px whose file holds
 * 6500 x 6500 pixels (169 MB decoded; the file is a few kilobytes): every
 * page has a part of its own, so that nothing is shared between them.
 */
export function hugePicturesDocx(count: number): Promise<Uint8Array> {
  if (!hugePicture) hugePicture = png(6500, 6500, RED, BLUE);
  let body = '';
  const rels: [string, string, string][] = [];
  const parts: [string, Uint8Array][] = [];
  for (let i = 1; i <= count; i++) {
    body += p(picture(400, 300, `rIdBig${i}`), i > 1 ? '<w:pageBreakBefore/>' : '');
    rels.push([`rIdBig${i}`, 'image', `media/big${i}.png`]);
    parts.push([`word/media/big${i}.png`, hugePicture]);
  }
  return buildDocx({ styles: DOC_STYLES, body: body + docSection(), rels, parts });
}

/** A text box of the given size, `x` px into the column and `y` px below its paragraph, that text does not wrap around. */
export const textBoxRun = (x: number, y: number, width: number, height: number, inner: string) =>
  '<w:r><w:drawing><wp:anchor distT="0" distB="0" distL="0" distR="0" simplePos="0" relativeHeight="1" behindDoc="0" locked="0" layoutInCell="1" allowOverlap="1">' +
  `<wp:simplePos x="0" y="0"/><wp:positionH relativeFrom="column"><wp:posOffset>${x * PX}</wp:posOffset></wp:positionH>` +
  `<wp:positionV relativeFrom="paragraph"><wp:posOffset>${y * PX}</wp:posOffset></wp:positionV>` +
  `<wp:extent cx="${width * PX}" cy="${height * PX}"/><wp:wrapNone/><wp:docPr id="7" name="Box"/>` +
  '<a:graphic><a:graphicData uri="http://schemas.microsoft.com/office/word/2010/wordprocessingShape"><wps:wsp>' +
  '<wps:spPr><a:solidFill><a:srgbClr val="00B400"/></a:solidFill></wps:spPr>' +
  `<wps:txbx><w:txbxContent>${inner}</w:txbxContent></wps:txbx><wps:bodyPr/></wps:wsp></a:graphicData></a:graphic></wp:anchor></w:drawing></w:r>`;
